    private static final java.util.concurrent.ThreadPoolExecutor optionalReader=new java.util.concurrent.ThreadPoolExecutor(1,1,0L,java.util.concurrent.TimeUnit.MILLISECONDS,new java.util.concurrent.ArrayBlockingQueue<>(8),r->new Thread(r,"Tonight saved rows"),new java.util.concurrent.ThreadPoolExecutor.AbortPolicy());
    private static final class OptionalRow {
        final Activity activity;final String kind;final TextView value;TextView subtitle;long record;String goal="";
        OptionalRow(Activity a,LinearLayout parent,String kind){activity=a;this.kind=kind;value=nightRow(parent,kind.equals(TonightLayout.GOAL_BANK)?"report":"calendar",TonightLayout.title(kind),"Loading…","Reading saved data",this::open,v->subtitle=v);}
        void open(){if(activity.isDestroyed()||!activity.hasWindowFocus())return;if(kind.equals(TonightLayout.GOAL_BANK)){android.content.Intent intent=RecordUi.intent(activity,GoalBankActivity.class);if(!goal.isEmpty())intent.putExtra("goal",goal);activity.startActivity(intent);}else activity.startActivity(record>0?RecordUi.intent(activity,RecordReportActivity.class).putExtra("record",record):RecordUi.intent(activity,HistoryActivity.class));}
        void show(String amount,String detail){value.setText(amount);subtitle.setText(detail);}
    }
    /** View-owned, read-only worker: detached old Tonight renders never publish stale results. */
    private static final class OptionalRead implements View.OnAttachStateChangeListener {
        final Activity activity;final android.content.Context app;final View host;final List<OptionalRow> rows;final long now;final Records.Factory records;final SleepPlans.Factory plans;volatile boolean closed;boolean started;
        OptionalRead(Activity a,View host,List<OptionalRow> rows,long now){activity=a;app=a.getApplicationContext();this.host=host;this.rows=List.copyOf(rows);this.now=now;records=Records.factory;plans=SleepPlans.factory;}
        void open(){host.addOnAttachStateChangeListener(this);if(host.isAttachedToWindow())start();}
        private void start(){if(started||closed)return;started=true;try{optionalReader.execute(()->{if(closed)return;List<RecordEntry> saved;try(Store store=records.open(app)){saved=Records.all(store);}catch(RuntimeException failed){publish(()->rows.forEach(r->r.show("Unavailable","Tap to open saved data or try again later")));return;}if(closed)return;
            RecordEntry latest=null;String latestError="";try{for(RecordEntry r:saved){if(r.edit.tags.stream().anyMatch(t->t.equalsIgnoreCase("nap"))||r.duration()<=0)continue;if(latest==null||r.edit.end>latest.edit.end)latest=r;}}catch(RuntimeException failed){latestError="Saved period needs review";}
            GoalCommitment selected=null;GoalProgress progress=null;String goalError="";boolean needsGoal=rows.stream().anyMatch(r->r.kind.equals(TonightLayout.GOAL_BANK));if(needsGoal)try{java.time.Instant time=java.time.Instant.ofEpochMilli(now);DatedGoalBank bank=new DatedGoalBank(new SleepPlans.Repository(plans.open(app)).goals(),saved,time);selected=bank.preferred(time);if(selected!=null)progress=bank.progress.get(selected.id);}catch(RuntimeException failed){goalError="Goal progress could not be read";}
            RecordEntry night=latest;GoalCommitment goal=selected;GoalProgress measured=progress;String nightFailure=latestError,goalFailure=goalError;
            publish(()->{for(OptionalRow row:rows){if(row.kind.equals(TonightLayout.GOAL_BANK)){if(!goalFailure.isEmpty())row.show("Unavailable",goalFailure+" · tap to review");else if(goal==null)row.show("No duration goal","Open your goal bank to choose a dated target");else{row.goal=goal.id;row.show(measured==null||measured.observed==0?"No recorded days":GoalProgress.signed(measured.balance),PlanActivity.duration(goal.target)+" target · "+(measured==null?"progress unavailable":measured.observed+" recorded, "+measured.unknown+" missing closed days"));}}else if(!nightFailure.isEmpty())row.show("Unavailable",nightFailure+" · tap to open history");else if(night==null)row.show("No saved night","Open sleep history to review or add a period");else{row.record=night.id;row.show(RecordUi.duration(night.duration()),RecordUi.date(night.edit.end,night.zone())+" · "+night.provenance());}}});
        });}catch(java.util.concurrent.RejectedExecutionException busy){rows.forEach(r->r.show("Unavailable","Saved data is busy · tap to open"));}}
        private void publish(Runnable action){activity.runOnUiThread(()->{if(!closed&&!activity.isDestroyed()&&host.isAttachedToWindow()&&Records.factory==records&&SleepPlans.factory==plans)action.run();});}
        @Override public void onViewAttachedToWindow(View v){start();}@Override public void onViewDetachedFromWindow(View v){closed=true;host.removeOnAttachStateChangeListener(this);}
    }
    private static void buttonRole(View view){view.setFocusable(true);view.setAccessibilityDelegate(new View.AccessibilityDelegate(){@Override public void onInitializeAccessibilityNodeInfo(View host,android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(host,info);info.setClassName(Button.class.getName());}});}
    private static String napStatus(Alarm alarm,NightWindow frame){return !alarm.nap.error.isEmpty()?"Nap needs attention":frame.now>=frame.end?"Nap ended":frame.now<frame.start?"Nap scheduled":"Nap running";}
