    private static TextView nightRow(LinearLayout p,String icon,String title,String value,String subtitle,Runnable click,java.util.function.Consumer<TextView> captureSubtitle){android.content.Context c=p.getContext();Appearance.Palette palette=Appearance.palette(c);LinearLayout row=Design.row(c);row.setMinimumHeight(Design.dp(c,subtitle==null?48:64));Design.Icon i=new Design.Icon(c,icon,palette.softInk);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(Design.dp(c,24),Design.dp(c,24));ip.rightMargin=Design.dp(c,20);row.addView(i,ip);LinearLayout text=Design.col(c);boolean stacked=Design.fontScale(c)>1.1f||captureSubtitle!=null;LinearLayout head=stacked?Design.col(c):Design.row(c);head.addView(Design.text(c,title,14,400,palette.softInk),new LinearLayout.LayoutParams(stacked?-1:0,-2,stacked?0:1));TextView valueView=Design.text(c,value,19,600,palette.softInk);head.addView(valueView);text.addView(head);if(subtitle!=null){Design.space(text,4);TextView sub=Design.text(text,subtitle,12,400,palette.softInk);if(captureSubtitle!=null)captureSubtitle.accept(sub);}row.addView(text,new LinearLayout.LayoutParams(0,-2,1));Design.Icon arrow=new Design.Icon(c,"chevron",palette.ink);LinearLayout.LayoutParams ar=new LinearLayout.LayoutParams(Design.dp(c,18),Design.dp(c,18));ar.leftMargin=Design.dp(c,10);row.addView(arrow,ar);row.setBackground(Design.touch(c,Color.TRANSPARENT,8));row.setOnClickListener(v->{InteractionFeedback.action(v);click.run();});buttonRole(row);row.setScreenReaderFocusable(true);p.addView(row);return valueView;}
